INSERT INTO `at_news` VALUES (1199, '519514', '美股涨幅收窄', NULL, '【美股涨幅收窄】金色财经报道，6月25日，美国股市涨幅收窄，部分股指转跌，标普500指数转跌0.03%，纳指转跌0.62%，道指最新涨0.44%。', '2026-06-25 21:50:58', 'jinse', NULL, 0, NULL, 1, '2026-06-25 22:06:12', NULL);
