INSERT INTO `at_news` VALUES (1674, '535714', '贝莱德IBIT持仓量突破80万枚BTC', NULL, '【贝莱德IBIT持仓量突破80万枚BTC】金色财经报道，贝莱德官方数据显示，截至10月8日，IBIT持仓市值达到65,186,275,578.49美元，持仓量触及804,753.63枚BTC。', '2026-10-11 06:29:08', 'jinse', NULL, 0, NULL, 1, '2026-10-11 09:23:48', NULL);
