-- ----------------------------
-- Table structure for ta_cal
-- ----------------------------
DROP TABLE IF EXISTS `ta_cal`;
CREATE TABLE `ta_cal`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `cal_date` datetime NOT NULL COMMENT '日历日期',
  `is_open` tinyint(4) NOT NULL COMMENT '是否开始1开市0休市',
  `week_day` tinyint(4) NOT NULL COMMENT '礼拜名称1-7',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6148 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci COMMENT = '交易日历表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ta_cal
-- ----------------------------

-- ----------------------------
-- Table structure for ta_stock_pick_diagnostic
-- ----------------------------
DROP TABLE IF EXISTS `ta_stock_pick_diagnostic`;
CREATE TABLE `ta_stock_pick_diagnostic`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主鍵ID',
  `symbol` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票代碼',
  `stock_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '股票名稱',
  `trade_date` date NOT NULL COMMENT '交易日期',
  `strategy_code` int(11) NOT NULL COMMENT '策略代码',
  `strategy_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '策略名稱',
  `passed` tinyint(1) NOT NULL COMMENT '是否通過篩選 (1:通過, 0:未通過)',
  `fail_reason` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '未通過時的攔截原因',
  `match_vcp` tinyint(1) NULL DEFAULT 0 COMMENT '是否符合VCP形態',
  `match_ma_coil` tinyint(1) NULL DEFAULT 0 COMMENT '是否符合均線粘合形態',
  `match_air_refuel` tinyint(1) NULL DEFAULT 0 COMMENT '是否符合空中加油形態',
  `close_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '當日收盤價',
  `change_rate` decimal(6, 4) NULL DEFAULT NULL COMMENT '當日漲跌幅',
  `vol_ratio` decimal(8, 4) NULL DEFAULT NULL COMMENT '放量倍數',
  `vcp_amplitude` decimal(6, 4) NULL DEFAULT NULL COMMENT 'VCP前期10日振幅',
  `macd_dif` decimal(10, 4) NULL DEFAULT NULL COMMENT 'MACD DIF',
  `macd_dea` decimal(10, 4) NULL DEFAULT NULL COMMENT 'MACD DEA',
  `macd_hist` decimal(10, 4) NULL DEFAULT NULL COMMENT 'MACD柱狀體',
  `kdj_k` decimal(8, 2) NULL DEFAULT NULL COMMENT 'KDJ K值',
  `kdj_d` decimal(8, 2) NULL DEFAULT NULL COMMENT 'KDJ D值',
  `rsi14` decimal(8, 2) NULL DEFAULT NULL COMMENT 'RSI 14數值',
  `obv` decimal(20, 4) NULL DEFAULT NULL COMMENT 'OBV能量潮數值',
  `profit_ratio` decimal(6, 4) NULL DEFAULT NULL COMMENT '獲利盤比例',
  `is_chip_single_peak` tinyint(1) NULL DEFAULT NULL COMMENT '是否籌碼單峰密集',
  `volume_score` decimal(6, 2) NULL DEFAULT NULL COMMENT '量價爆發力得分',
  `chip_score` decimal(6, 2) NULL DEFAULT NULL COMMENT '籌碼面得分',
  `momentum_score` decimal(6, 2) NULL DEFAULT NULL COMMENT '技術動能得分',
  `pattern_score` decimal(6, 2) NULL DEFAULT NULL COMMENT '形態品質得分',
  `total_score` decimal(6, 2) NULL DEFAULT NULL COMMENT '綜合總得分',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '記錄創建時間',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_date_passed`(`trade_date`, `passed`) USING BTREE,
  INDEX `idx_symbol_date`(`symbol`, `trade_date`) USING BTREE,
  INDEX `idx_fail_reason`(`fail_reason`) USING BTREE,
  INDEX `idx_total_score`(`total_score`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '選股策略診斷與回測明細表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ta_stock_pick_diagnostic
-- ----------------------------

-- ----------------------------
-- Table structure for ta_task
-- ----------------------------
DROP TABLE IF EXISTS `ta_task`;
CREATE TABLE `ta_task`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `start_begin_time` datetime NOT NULL COMMENT '任务启动起始时间',
  `start_end_time` datetime NOT NULL COMMENT '任务启动截止时间，一个任务如果截止时间已经过期，则不再被启动',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '任务完成时间',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '任务状态0未启动1正在进行2已经完成3已过期',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1688 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务规划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ta_task
-- ----------------------------

-- ----------------------------
-- Table structure for tf_account
-- ----------------------------
DROP TABLE IF EXISTS `tf_account`;
CREATE TABLE `tf_account`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主鍵 ID',
  `account_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '賬戶編號/策略標識',
  `initial_capital` decimal(15, 2) NOT NULL COMMENT '初始資金',
  `available_cash` decimal(15, 2) NOT NULL COMMENT '可用現金（可用於買入股票）',
  `frozen_cash` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '凍結現金（掛單未成交或手續費預凍結）',
  `market_value` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '持倉市值',
  `total_assets` decimal(15, 2) NOT NULL COMMENT '總資產（可用現金 + 凍結現金 + 持倉市值）',
  `total_pnl` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '累計盈虧金額',
  `total_pnl_pct` decimal(8, 4) NULL DEFAULT 0.0000 COMMENT '累計盈虧比例（收益率）',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '狀態：1-正常，0-凍結',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '創建時間',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_no`(`account_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '回測虛擬賬戶表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tf_account
-- ----------------------------

-- ----------------------------
-- Table structure for tf_fund_flow
-- ----------------------------
DROP TABLE IF EXISTS `tf_fund_flow`;
CREATE TABLE `tf_fund_flow`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主鍵 ID',
  `account_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '賬戶編號',
  `trade_date` date NOT NULL COMMENT '業務發生日期',
  `biz_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '業務類型：DEPOSIT-入金, WITHDRAW-出金, BUY-買入扣款, SELL-賣出回款, COMMISSION-傭金, TAX-印花稅',
  `amount` decimal(15, 2) NOT NULL COMMENT '變動金額（收入為正，支出為負）',
  `balance_after` decimal(15, 2) NOT NULL COMMENT '變動後的可用現金餘額',
  `related_order_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '關聯的訂單編號/流水號',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '備註說明',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '記錄時間',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_account_date`(`account_no`, `trade_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '回測資金流水明細表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tf_fund_flow
-- ----------------------------

-- ----------------------------
-- Table structure for tf_position
-- ----------------------------
DROP TABLE IF EXISTS `tf_position`;
CREATE TABLE `tf_position`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主鍵 ID',
  `account_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '賬戶編號',
  `symbol` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票代碼（例如 002792.SZ）',
  `stock_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票名稱',
  `total_volume` int(11) NOT NULL COMMENT '總持倉股數',
  `available_volume` int(11) NOT NULL COMMENT '可用股數（T+1：當天買入的為 0，次日解凍變為總股數）',
  `cost_price` decimal(10, 3) NOT NULL COMMENT '持倉成本價（加權平均成本）',
  `current_price` decimal(10, 3) NOT NULL COMMENT '當前最新價/收盤價',
  `market_value` decimal(15, 2) NOT NULL COMMENT '當前持倉市值（total_volume * current_price）',
  `unrealized_pnl` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '浮動盈虧金額',
  `unrealized_pnl_pct` decimal(8, 4) NULL DEFAULT 0.0000 COMMENT '浮動盈虧比例',
  `open_date` date NOT NULL COMMENT '建倉日期',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '創建時間',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新時間',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account_symbol`(`account_no`, `symbol`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '回測當前持倉表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tf_position
-- ----------------------------

-- ----------------------------
-- Table structure for tf_risk_ann
-- ----------------------------
DROP TABLE IF EXISTS `tf_risk_ann`;
CREATE TABLE `tf_risk_ann`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `publish_time` datetime NOT NULL COMMENT '发布时间',
  `stock_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票代号',
  `stock_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '股票名称',
  `market_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市场代码',
  `ann_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公告类型',
  `source_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息类型',
  `art_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文章编码',
  `title` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '公告标题',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '公告内容',
  `file_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公告文件url',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_stock_news_art_code`(`publish_time`, `art_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '股票风险公告' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tf_risk_ann
-- ----------------------------

-- ----------------------------
-- Table structure for tf_risk_report
-- ----------------------------
DROP TABLE IF EXISTS `tf_risk_report`;
CREATE TABLE `tf_risk_report`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `stock_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票代码',
  `stock_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票名称',
  `market_type` tinyint(4) NOT NULL COMMENT '市场类型：1-A股，2-港股，3-美股',
  `risk_ann_id` bigint(20) NOT NULL COMMENT '风险公告ID',
  `input_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'AI输入参数',
  `output_response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'AI输出结果',
  `passed` tinyint(4) NULL DEFAULT 0 COMMENT 'AI复核是否通过：0-未通过，1-通过',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI风险研报表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tf_risk_report
-- ----------------------------

-- ----------------------------
-- Table structure for tf_risk_report_ann
-- ----------------------------
DROP TABLE IF EXISTS `tf_risk_report_ann`;
CREATE TABLE `tf_risk_report_ann`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `risk_report_id` bigint(20) NOT NULL COMMENT '风险研报ID',
  `risk_ann_id` bigint(20) NOT NULL COMMENT '风险公告ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风险研报公告关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tf_risk_report_ann
-- ----------------------------

-- ----------------------------
-- Table structure for tf_trade_execution
-- ----------------------------
DROP TABLE IF EXISTS `tf_trade_execution`;
CREATE TABLE `tf_trade_execution`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主鍵 ID',
  `account_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '賬戶編號',
  `order_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '訂單編號',
  `symbol` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票代碼',
  `stock_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '股票名稱',
  `trade_side` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易方向：BUY-買入, SELL-賣出',
  `trade_price` decimal(10, 3) NOT NULL COMMENT '成交價格',
  `trade_volume` int(11) NOT NULL COMMENT '成交股數',
  `trade_amount` decimal(15, 2) NOT NULL COMMENT '成交總金額（價格 * 股數）',
  `commission` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '交易傭金',
  `tax` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '印花稅（僅賣出時收取）',
  `realized_pnl` decimal(15, 2) NULL DEFAULT 0.00 COMMENT '平倉實現盈虧（僅賣出時計算）',
  `trade_time` datetime NOT NULL COMMENT '成交時間（回測中的模擬撮合時間點）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '記錄時間',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_account_symbol`(`account_no`, `symbol`) USING BTREE,
  INDEX `idx_trade_time`(`trade_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '回測歷史成交交割單表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tf_trade_execution
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
